ue="<?php echo e(getCsrfToken());?>"><input type="hidden" name="action" value="delete_banner"><input type="hidden" name="id" value="<?php echo (int)$b['id'];?>"><button class="btn btn-danger">ลบแบนเนอร์</button></form></details><?php endforeach;?></section>
